SET @prov_c := '%s';
SET @id:= '%s';
SET @cat_id := '%s';
SET @send :=  IF((SELECT active FROM sys_report WHERE cat_id = @cat_id and id = @id )=1,0,2);
SET @b_year:=(SELECT yearprocess FROM pk_byear LIMIT 1);
SET	@start_d:=concat(@b_year-1,'1001');
SET @end_d:=concat(@b_year,'0930');

CREATE TABLE IF NOT EXISTS s_ckd_stage_typearea(
  id varchar(32) NOT NULL,
  hospcode varchar(5) NOT NULL,
  areacode varchar(8) NOT NULL,
  flag_sent varchar(1) NOT NULL,
  date_com varchar(14) NOT NULL,
  b_year varchar(4) NOT NULL,
	stage1 int(9) DEFAULT 0,
	stage2 int(9) DEFAULT 0,
	stage3 int(9) DEFAULT 0,
	stage4 int(9) DEFAULT 0,
	stage5 int(9) DEFAULT 0,
	PRIMARY KEY (id,hospcode,areacode,b_year),
	KEY (hospcode),
	KEY (areacode),
	KEY (b_year)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

DELETE FROM s_ckd_stage_typearea WHERE id=@id AND b_year=(@b_year+543);

INSERT IGNORE INTO s_ckd_stage_typearea
(
SELECT
	 @id,p.check_hosp hospcode,p.check_vhid areacode
   ,@send,DATE_FORMAT(now(),'%Y%m%d%H%i') as d_com,@b_year+543 as b_year
,COUNT(DISTINCT if(egfr_r1 >=90  ,CONCAT(p.HOSPCODE,'-',p.pid),NULL)) s1
,COUNT(DISTINCT if(egfr_r1 BETWEEN 60 AND 89.99  ,CONCAT(p.HOSPCODE,'-',p.pid),NULL)) s2
,COUNT(DISTINCT if(egfr_r1 BETWEEN 30 AND 59.99  ,CONCAT(p.HOSPCODE,'-',p.pid),NULL)) s3
,COUNT(DISTINCT if(egfr_r1 BETWEEN 15 AND 29.99  ,CONCAT(p.HOSPCODE,'-',p.pid),NULL)) s4
,COUNT(DISTINCT if(egfr_r1 < 15  ,CONCAT(p.HOSPCODE,'-',p.pid),NULL)) s5
FROM
(SELECT * FROM (SELECT * FROM t_ckd_egfr ORDER BY egfr_d1 DESC) g GROUP BY cid)  g 
 INNER JOIN t_person_cid p ON g.cid=p.cid
 INNER JOIN chospital h ON p.HOSPCODE=h.hoscode
WHERE egfr_r1 >0 AND p.check_typearea in(1,3) AND  p.discharge in(9) AND p.nation in(99)
AND SUBSTR(p.check_vhid,1,2) in(@prov_c) AND h.provcode in(@prov_c)
GROUP BY p.check_hosp,p.check_vhid

);

