SET @prov_c:=(SELECT provincecode FROM sys_config LIMIT 1);
SET @b_year:=(SELECT yearprocess FROM pk_byear LIMIT 1);
SET @start_d:=concat(@b_year-1,'1001');
SET @end_d:=concat(@b_year,'0930');

DROP TEMPORARY TABLE IF EXISTS tx;
CREATE TEMPORARY TABLE IF NOT EXISTS tx(
SELECT 
h.hoscode as hospcode ,h.hosname, p.PID, p.CID, p.NAME, p.LNAME, p.SEX, p.BIRTH, p.addr, p.check_vhid, p.NATION,p.DISCHARGE,p.check_typearea
,ROUND(egfr_r1,2) AS egfr_r1
,if(egfr_r1 >=90, 1,
  if(egfr_r1 BETWEEN 60 AND 89.99 , 2,
	if(egfr_r1 BETWEEN 30 AND 59.99, 3,
	if(egfr_r1 BETWEEN 15 AND 29.99 , 4,
	if(egfr_r1 < 15 ,5,NULL))))) stage
FROM t_ckd_egfr g 
INNER JOIN t_person_cid p ON  g.CID=p.CID
INNER JOIN chospital h ON p.check_hosp=h.hoscode
WHERE egfr_r1 >0  AND p.check_typearea IN(1,3) AND p.discharge IN(9)
);
SELECT
h.hoscode, h.hosname, p.PID, p.CID, p.NAME, p.LNAME, p.SEX, p.BIRTH, p.addr, p.check_vhid, p.NATION
,p.egfr_r1,p.stage,p.DISCHARGE,p.check_typearea
FROM
tx p INNER JOIN chospital h ON p.HOSPCODE=h.hoscode
WHERE 1=1 {where}
